insert into public.textos (id, conteudo) values
  (1, 'A saúde pública brasileira enfrenta o desafio de conciliar demandas crescentes com recursos limitados. Nos municípios, onde o cidadão de fato vive, as equipes de atenção básica tornam-se a porta de entrada do sistema. Contudo, não basta ampliar o número de unidades: é preciso qualificar o cuidado, fortalecer vínculos e garantir que a informação circule entre os serviços. Quando isso ocorre, evitam-se internações desnecessárias e o paciente é atendido no lugar certo, no tempo certo.'),
  (2, 'O trabalho em turnos é uma realidade para grande parte dos profissionais de enfermagem. Embora garanta a continuidade do cuidado, o plantão noturno altera o ritmo biológico e pode comprometer a qualidade do sono. Estudos indicam que trabalhadores privados de descanso cometem mais erros, sobretudo em tarefas que exigem atenção contínua, como o preparo de medicamentos. Por isso, especialistas recomendam que as instituições organizem escalas mais equilibradas e ofereçam espaços adequados para pausas. Cuidar de quem cuida, afinal, também é uma forma de proteger o paciente.'),
  (3, 'Durante décadas, o Brasil foi referência mundial em vacinação. Campanhas bem planejadas e a capilaridade das salas de vacina fizeram com que doenças como a poliomielite deixassem de circular no país. Nos últimos anos, porém, as coberturas vacinais caíram. Entre as causas apontadas estão a falsa sensação de segurança — já que muitos nunca viram essas doenças —, horários de atendimento pouco flexíveis e a circulação de notícias falsas. Reverter esse quadro exige informação de qualidade, mas também serviços que se adaptem à rotina da população.'),
  (4, 'A população brasileira envelhece em ritmo acelerado. Se em países europeus a transição demográfica levou mais de um século, aqui ela ocorre em poucas décadas. Essa velocidade impõe desafios ao sistema de saúde, que precisa lidar com o aumento das doenças crônicas e com a necessidade de cuidados prolongados. Mais do que acrescentar anos à vida, trata-se de acrescentar vida aos anos: garantir autonomia, participação social e dignidade a quem envelhece.'),
  (5, 'Acolher não é apenas receber bem. No cotidiano dos serviços, o acolhimento envolve escutar a queixa, reconhecer o que é prioridade e assumir a responsabilidade pela resposta, ainda que ela implique encaminhar o usuário a outro ponto da rede. Quando reduzido a uma triagem burocrática, perde seu sentido. Bem praticado, porém, transforma a relação entre profissionais e população, porque faz do serviço um lugar onde as pessoas se sentem ouvidas.'),
  (6, 'Saneamento básico é saúde. Cada real investido em água tratada e esgotamento sanitário reduz gastos com internações por doenças de veiculação hídrica, como diarreias e hepatite A. Apesar disso, milhões de brasileiros ainda vivem sem coleta de esgoto. O problema, que atinge principalmente as periferias urbanas e as áreas rurais, revela que as desigualdades sociais se expressam também no acesso a direitos básicos.')
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-001', 'pt', 1, 'De acordo com o texto, a principal ideia defendida é que:', '["a ampliação da atenção básica precisa vir acompanhada de qualificação do cuidado e de integração entre os serviços.","o número de unidades básicas no Brasil já é suficiente e não deve ser ampliado.","as internações hospitalares devem ser integralmente substituídas pela atenção básica.","os municípios dispõem de recursos ilimitados para a saúde pública.","a circulação de informação entre serviços é irrelevante quando há muitas unidades."]'::jsonb, 0, 'O autor afirma que "não basta ampliar": é preciso qualificar o cuidado, fortalecer vínculos e garantir a circulação da informação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-002', 'pt', 1, 'No trecho "Contudo, não basta ampliar o número de unidades", o conectivo "Contudo" pode ser substituído, sem alteração de sentido, por:', '["No entanto","Portanto","Porque","Assim que","Por conseguinte"]'::jsonb, 0, '"Contudo" é conjunção adversativa, equivalente a "no entanto", "todavia", "porém". "Portanto" e "por conseguinte" são conclusivas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-003', 'pt', 1, 'Em "Nos municípios, onde o cidadão de fato vive", o termo "onde" retoma:', '["municípios","cidadão","equipes","sistema","desafio"]'::jsonb, 0, '"Onde" é pronome relativo que indica lugar e retoma o antecedente "municípios".') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-004', 'pt', 1, 'Em "evitam-se internações desnecessárias", o verbo está no plural porque:', '["concorda com o sujeito \"internações desnecessárias\", em construção de voz passiva sintética.","o sujeito é indeterminado, marcado pelo pronome \"se\".","concorda com o termo \"informação\", citado anteriormente.","trata-se de verbo impessoal, que sempre vai ao plural.","concorda com o termo \"serviços\", da oração anterior."]'::jsonb, 0, 'Verbo transitivo direto + "se" = voz passiva sintética: "internações desnecessárias são evitadas". O verbo concorda com o sujeito paciente.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-005', 'pt', null, 'Assinale a frase em que o acento indicativo de crase está empregado corretamente:', '["O enfermeiro referiu-se à paciente do leito 4.","A equipe começou à trabalhar cedo.","Entregou o relatório à ela no fim do plantão.","O curativo será feito à partir das 8h.","Ficou frente à frente com o coordenador."]'::jsonb, 0, '"Referir-se a" + "a paciente" = à. Não há crase antes de verbo, de pronome pessoal (ela) nem em expressões com palavras repetidas (frente a frente); "a partir" também não tem crase.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-006', 'pt', null, 'Quanto à regência, de acordo com a norma-padrão, está correta a frase:', '["O técnico assistiu ao parto realizado no hospital.","Prefiro mais o plantão diurno do que o noturno.","Os pacientes obedecem o protocolo da unidade.","Esqueci do horário da medicação.","Ela namora com um enfermeiro do setor."]'::jsonb, 0, '"Assistir" no sentido de presenciar exige a preposição "a". Correções: prefiro X a Y; obedecem ao protocolo; esqueci o horário (ou esqueci-me do); namora um enfermeiro.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-007', 'pt', null, 'Assinale a alternativa corretamente pontuada:', '["Durante o plantão, os técnicos verificaram os sinais vitais de todos os pacientes.","Os técnicos de enfermagem, verificaram os sinais vitais.","O enfermeiro, entregou a escala ao coordenador.","A paciente que, chegou ontem recebeu alta.","Precisamos de: luvas máscaras e aventais."]'::jsonb, 0, 'A vírgula após adjunto adverbial deslocado é adequada. Não se separa sujeito do verbo por vírgula, e itens de enumeração devem ser separados por vírgula.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-008', 'pt', null, 'Quanto à colocação pronominal, segundo a norma-padrão, está correta a frase:', '["Não se deve administrar o medicamento sem prescrição.","Me entregue o prontuário, por favor.","Ninguém informou-me sobre a mudança de escala.","Quando avisaram-no, já era tarde.","Tinha esquecido-se do horário."]'::jsonb, 0, 'Palavras negativas (não, ninguém) e conjunções subordinativas (quando) atraem o pronome (próclise). Não se inicia frase com pronome oblíquo e não se usa ênclise ao particípio.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-009', 'pt', null, 'A palavra "saúde" é acentuada pela mesma regra que justifica o acento em:', '["juízo","médico","também","útil","pé"]'::jsonb, 0, 'Em "saúde" e "juízo", acentua-se o "i" ou "u" tônico que forma hiato com a vogal anterior. Médico = proparoxítona; também = oxítona em -em; útil = paroxítona em -l; pé = monossílabo tônico em -e.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-010', 'pt', 1, 'No texto, a palavra "conciliar" ("conciliar demandas crescentes com recursos limitados") tem sentido equivalente a:', '["harmonizar","separar","reduzir","ignorar","multiplicar"]'::jsonb, 0, 'Conciliar = pôr em acordo, harmonizar, compatibilizar.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-011', 'pt', 2, 'A ideia central do texto é que:', '["garantir o descanso dos profissionais de enfermagem é também uma medida de segurança para o paciente.","o plantão noturno deve ser extinto nas instituições de saúde.","os erros de medicação decorrem exclusivamente da falta de conhecimento técnico.","o trabalho em turnos não interfere no ritmo biológico.","as pausas durante o plantão prejudicam a continuidade do cuidado."]'::jsonb, 0, 'O texto relaciona privação de sono a erros e conclui que "cuidar de quem cuida" protege o paciente.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-012', 'pt', 2, 'No trecho "Embora garanta a continuidade do cuidado", a conjunção "Embora" estabelece relação de:', '["concessão.","causa.","finalidade.","conclusão.","proporção."]'::jsonb, 0, '"Embora" é conjunção concessiva, equivalente a "ainda que", "mesmo que".') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-013', 'pt', 2, 'A palavra "sobretudo", em "sobretudo em tarefas que exigem atenção contínua", pode ser substituída, sem alteração de sentido, por:', '["principalmente.","raramente.","apenas.","contudo.","inclusive não."]'::jsonb, 0, '"Sobretudo" é advérbio que indica destaque: principalmente, especialmente.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-014', 'pt', 2, 'No trecho "Por isso, especialistas recomendam...", a expressão "Por isso" introduz:', '["uma conclusão decorrente do que foi dito antes.","uma oposição ao que foi dito antes.","uma condição para o que foi dito antes.","um exemplo do que foi dito antes.","uma comparação com o que foi dito antes."]'::jsonb, 0, '"Por isso" retoma a informação anterior (mais erros por privação de sono) e introduz sua consequência.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-015', 'pt', 2, 'Em "tarefas que exigem atenção contínua", o termo "que" retoma:', '["tarefas.","erros.","trabalhadores.","estudos.","medicamentos."]'::jsonb, 0, '"Que" é pronome relativo; quem "exige atenção contínua" são as tarefas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-016', 'pt', 3, 'Segundo o texto, NÃO é apontada como causa da queda das coberturas vacinais:', '["a falta de vacinas nos estoques.","a falsa sensação de segurança.","os horários de atendimento pouco flexíveis.","a circulação de notícias falsas.","o fato de muitos nunca terem visto essas doenças."]'::jsonb, 0, 'O texto cita sensação de segurança, horários pouco flexíveis e notícias falsas; não fala em desabastecimento.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-017', 'pt', 3, 'No texto, os travessões em "— já que muitos nunca viram essas doenças —" foram empregados para:', '["isolar uma explicação inserida no período.","indicar a fala de um personagem.","marcar uma enumeração.","substituir os dois-pontos de uma citação.","indicar o fim do período."]'::jsonb, 0, 'Os travessões duplos isolam um comentário explicativo, como fariam vírgulas ou parênteses.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-018', 'pt', 3, 'No texto, a expressão "capilaridade das salas de vacina" refere-se:', '["à ampla distribuição das salas de vacina pelo território.","ao tamanho reduzido das salas de vacina.","à falta de salas de vacina no interior.","ao uso de agulhas finas na vacinação.","à concentração das salas de vacina nas capitais."]'::jsonb, 0, 'Em sentido figurado, capilaridade é a capacidade de alcançar pontos distantes, como os vasos capilares.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-019', 'pt', 3, 'Em "Nos últimos anos, porém, as coberturas vacinais caíram", o termo "porém" estabelece relação de:', '["oposição em relação à ideia de que o Brasil era referência em vacinação.","causa da queda das coberturas.","tempo em que a queda ocorreu.","conclusão sobre as campanhas.","adição de uma nova causa."]'::jsonb, 0, '"Porém" é conjunção adversativa: contrasta o passado de sucesso com a queda atual.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-020', 'pt', 3, 'No período "Reverter esse quadro exige informação de qualidade", o sujeito do verbo "exige" é:', '["a oração \"Reverter esse quadro\".","\"informação de qualidade\".","\"esse quadro\".","indeterminado.","inexistente (oração sem sujeito)."]'::jsonb, 0, 'O sujeito é oracional: "[Reverter esse quadro] exige...". "Informação de qualidade" é objeto direto.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-021', 'pt', 4, 'No período "Se em países europeus a transição demográfica levou mais de um século, aqui ela ocorre em poucas décadas", o autor estabelece principalmente uma relação de:', '["contraste entre a velocidade do envelhecimento na Europa e no Brasil.","condição para que o Brasil envelheça.","finalidade do envelhecimento europeu.","consequência do envelhecimento europeu sobre o Brasil.","concordância entre as duas realidades."]'::jsonb, 0, 'Apesar do "se", não há condição real: a construção compara/contrasta os dois ritmos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-022', 'pt', 4, 'Em "Mais do que acrescentar anos à vida, trata-se de acrescentar vida aos anos", o autor:', '["inverte os termos para enfatizar que o foco deve ser a qualidade de vida na velhice.","defende que o principal objetivo é aumentar a expectativa de vida.","critica a autonomia da pessoa idosa.","afirma que os anos de vida não podem ser aumentados.","contradiz a ideia apresentada no início do texto."]'::jsonb, 0, 'A inversão (anos à vida / vida aos anos) destaca a qualidade, explicada após os dois-pontos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-023', 'pt', 4, 'No texto, os dois-pontos após "acrescentar vida aos anos" introduzem:', '["uma explicação do que significa \"acrescentar vida aos anos\".","uma fala direta.","uma ideia contrária à anterior.","uma pergunta retórica.","a conclusão de uma enumeração anterior."]'::jsonb, 0, 'Os dois-pontos anunciam o esclarecimento: autonomia, participação social e dignidade.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-024', 'pt', 4, 'Em "ao sistema de saúde, que precisa lidar com o aumento das doenças crônicas", o pronome "que" retoma:', '["sistema de saúde.","desafios.","velocidade.","doenças crônicas.","população brasileira."]'::jsonb, 0, 'Quem precisa lidar com as doenças crônicas é o sistema de saúde.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-025', 'pt', 4, 'O acento grave em "acrescentar anos à vida" justifica-se porque:', '["o verbo \"acrescentar\" exige a preposição \"a\", que se funde ao artigo feminino \"a\" de \"vida\".","\"vida\" é palavra feminina, e toda palavra feminina recebe crase.","há uma locução adverbial de tempo.","se trata de uma expressão de modo.","o acento é facultativo e poderia ser retirado."]'::jsonb, 0, 'Acrescentar algo A alguma coisa + artigo "a" = à.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-026', 'pt', 5, 'De acordo com o texto, o acolhimento:', '["envolve escuta e responsabilização, e perde o sentido quando reduzido a uma triagem burocrática.","consiste apenas em receber bem o usuário na recepção.","dispensa o encaminhamento a outros pontos da rede.","é sinônimo de triagem administrativa.","deve ser feito exclusivamente pelo médico."]'::jsonb, 0, 'O texto define acolhimento como escutar, priorizar e assumir a resposta, criticando a triagem meramente burocrática.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-027', 'pt', 5, 'Em "ainda que ela implique encaminhar o usuário a outro ponto da rede", a expressão "ainda que" pode ser substituída, sem prejuízo de sentido, por:', '["mesmo que.","porque.","desde que.","para que.","à medida que."]'::jsonb, 0, '"Ainda que" e "mesmo que" são locuções concessivas. "Desde que" seria condicional.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-028', 'pt', 5, 'Em "Quando reduzido a uma triagem burocrática, perde seu sentido", o sujeito de "perde" é:', '["\"o acolhimento\", que está elíptico (subentendido).","\"uma triagem burocrática\".","\"seu sentido\".","indeterminado.","\"o usuário\"."]'::jsonb, 0, 'O sujeito oculto retoma "o acolhimento", termo do período anterior.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-029', 'pt', 5, 'No último período, a conjunção "porque" introduz:', '["a causa/explicação de o acolhimento transformar a relação entre profissionais e população.","uma condição para o acolhimento ocorrer.","uma finalidade do serviço de saúde.","uma oposição ao acolhimento.","uma consequência da triagem burocrática."]'::jsonb, 0, '"Porque" introduz a razão pela qual o acolhimento bem praticado transforma a relação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-030', 'pt', 5, 'Em "as pessoas se sentem ouvidas", o pronome "se":', '["integra o verbo pronominal \"sentir-se\".","é partícula apassivadora.","é índice de indeterminação do sujeito.","é conjunção condicional.","é conjunção integrante."]'::jsonb, 0, '"Sentir-se" (perceber-se em determinado estado) é verbo pronominal.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-031', 'pt', 6, 'Em "Apesar disso, milhões de brasileiros ainda vivem sem coleta de esgoto", a expressão "Apesar disso" retoma:', '["a informação de que o investimento em saneamento reduz gastos com internações.","a falta de coleta de esgoto.","as periferias urbanas.","as desigualdades sociais.","a hepatite A."]'::jsonb, 0, '"Disso" retoma o benefício do saneamento; "apesar de" marca a concessão: mesmo com esse benefício, falta esgoto.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-032', 'pt', 6, 'A oração "que atinge principalmente as periferias urbanas e as áreas rurais", por estar entre vírgulas, tem valor:', '["explicativo.","restritivo.","condicional.","temporal.","final."]'::jsonb, 0, 'Oração adjetiva entre vírgulas é explicativa: acrescenta uma informação sobre "o problema".') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-033', 'pt', 6, 'No texto, "doenças de veiculação hídrica" são doenças:', '["transmitidas pela água.","transmitidas pelo ar.","causadas pelo excesso de chuvas.","hereditárias.","transmitidas por insetos."]'::jsonb, 0, 'Veiculação hídrica = transmissão pela água (exemplos do texto: diarreias e hepatite A).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-034', 'pt', 6, 'Infere-se do texto que o autor considera o saneamento básico:', '["um direito básico cuja ausência revela desigualdade social.","um gasto que não tem relação com a saúde.","um problema exclusivo das áreas rurais.","uma questão já resolvida no Brasil.","responsabilidade individual de cada morador."]'::jsonb, 0, 'O texto abre com "Saneamento básico é saúde" e fecha associando sua falta às desigualdades no acesso a direitos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-035', 'pt', 6, 'Em "milhões de brasileiros ainda vivem sem coleta de esgoto", o verbo está no plural porque concorda com:', '["\"milhões\", núcleo do sujeito.","\"brasileiros\", que é o objeto direto.","\"coleta\".","\"esgoto\".","o sujeito indeterminado."]'::jsonb, 0, 'O núcleo do sujeito é "milhões" (substantivo masculino plural).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-036', 'pt', null, 'Assinale a frase correta quanto à concordância verbal:', '["Fazia dois anos que ela trabalhava no hospital.","Fazem dois anos que ela trabalha no hospital.","Houveram muitos atendimentos no plantão.","Devem haver vagas para técnicos.","Existe muitas dúvidas sobre o protocolo."]'::jsonb, 0, '"Fazer" indicando tempo e "haver" (existir) são impessoais: ficam no singular, inclusive o auxiliar ("deve haver"). "Existir" concorda: existem muitas dúvidas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-037', 'pt', null, 'Assinale a frase correta quanto à concordância nominal:', '["As fichas seguem anexas ao prontuário.","Era meio-dia e meio quando a paciente chegou.","Havia bastante pacientes na fila.","Ela mesmo assinou o termo.","Hoje tivemos menas intercorrências."]'::jsonb, 0, '"Anexo" concorda com o substantivo. Correções: meio-dia e meia; bastantes pacientes; ela mesma; menos (invariável).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-038', 'pt', null, 'Assinale a frase correta quanto à regência verbal:', '["O atraso implicou prejuízo ao paciente.","Chegamos no hospital às 7h.","Ela aspira um cargo de coordenação.","O paciente simpatizou-se com a enfermeira.","Prefiro café do que chá."]'::jsonb, 0, '"Implicar" (acarretar) é transitivo direto. Correções: chegar a; aspirar a (desejar); simpatizar com (não pronominal); preferir algo a algo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-039', 'pt', null, 'O acento indicativo de crase está empregado corretamente em:', '["O plantão começa às 7 horas.","Fomos à pé até a unidade.","Ele se referiu à essa questão.","Volto daqui à pouco.","Entregou o comunicado à todos."]'::jsonb, 0, 'Há crase em horas determinadas. Não há crase antes de palavra masculina, de pronome demonstrativo "essa", de pronome indefinido ou na expressão "daqui a".') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-040', 'pt', null, 'O uso do acento grave é FACULTATIVO em:', '["Entreguei o laudo à minha supervisora.","Cheguei à unidade às 7h.","Ele assistiu à reunião.","Dirigiu-se à recepção.","Fez referência à lei."]'::jsonb, 0, 'Antes de pronome possessivo feminino o artigo é opcional, logo a crase também.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-041', 'pt', null, 'Assinale a alternativa em que o emprego de "por que / porque / porquê / por quê" está correto:', '["Não sei por que ele faltou ao plantão.","Ele faltou por quê estava doente.","Porque você não veio ontem?","Explique o porque da decisão.","Você faltou porque?"]'::jsonb, 0, '"Por que" separado em pergunta direta/indireta; "porque" em resposta (causa); "porquê" substantivado; "por quê" em final de frase.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-042', 'pt', null, 'Assinale a alternativa em que todas as palavras estão grafadas corretamente:', '["exceção, análise, privilégio.","excessão, análise, privilégio.","exceção, análize, privilégio.","exceção, análise, previlégio.","excessão, análize, previlégio."]'::jsonb, 0, 'Grafias corretas: exceção (ç), análise (s), privilégio (pri-).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-043', 'pt', null, 'Assinale a alternativa em que todas as palavras estão grafadas corretamente:', '["paralisação, pesquisa, obsessão.","paralização, pesquisa, obsessão.","paralisação, pesquiza, obsessão.","paralisação, pesquisa, obcessão.","paralização, pesquiza, obcessão."]'::jsonb, 0, 'Paralisação deriva de paralisar (s); pesquisa (s); obsessão (bs + ss).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-044', 'pt', null, 'De acordo com o Novo Acordo Ortográfico, está correta a grafia de:', '["micro-ondas, anti-inflamatório, autoestima.","microondas, antiinflamatório, auto-estima.","micro-ondas, antiinflamatório, auto-estima.","microondas, anti-inflamatório, autoestima.","micro-ondas, anti-inflamatório, auto-estima."]'::jsonb, 0, 'Usa-se hífen quando o prefixo termina na mesma vogal que inicia o segundo elemento (micro-ondas, anti-inflamatório); prefixo terminado em vogal diferente se junta (autoestima).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-045', 'pt', null, 'De acordo com o Novo Acordo Ortográfico, estão corretamente grafadas:', '["ideia, heroico, voo.","idéia, heróico, vôo.","ideia, heróico, vôo.","idéia, heroico, voo.","ideia, heroico, vôo."]'::jsonb, 0, 'Caiu o acento dos ditongos abertos ei/oi em paroxítonas e do hiato oo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-046', 'pt', null, 'Em "A paciente chegou muito cansada", a palavra "muito" é classificada como:', '["advérbio.","adjetivo.","pronome indefinido.","substantivo.","conjunção."]'::jsonb, 0, '"Muito" intensifica o adjetivo "cansada": é advérbio de intensidade (invariável).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-047', 'pt', null, 'Assinale a oração sem sujeito:', '["Choveu muito durante a madrugada.","Os pacientes chegaram cedo.","Precisa-se de técnicos de enfermagem.","Disseram que haverá mudança na escala.","Saímos tarde do plantão."]'::jsonb, 0, 'Verbos que indicam fenômenos da natureza são impessoais. "Precisa-se" e "Disseram" têm sujeito indeterminado; "Saímos", sujeito oculto (nós).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-048', 'pt', null, 'A transposição correta de "A enfermeira aplicou a vacina" para a voz passiva analítica é:', '["A vacina foi aplicada pela enfermeira.","A vacina aplicou-se pela enfermeira.","Aplicou-se a vacina.","A vacina era aplicada pela enfermeira.","A enfermeira foi aplicada pela vacina."]'::jsonb, 0, 'Voz passiva analítica: ser + particípio, mantendo o tempo verbal (pretérito perfeito: foi aplicada).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-049', 'pt', null, 'Assinale a frase correta quanto à flexão verbal:', '["Quando você vir a enfermeira, entregue o recado.","Quando você ver a enfermeira, entregue o recado.","Se o gestor intervir, o problema será resolvido.","Se eu propor uma mudança, você aceita?","Quando ele repor o estoque, avise."]'::jsonb, 0, 'Futuro do subjuntivo: ver → vir; intervir → intervier; propor → propuser; repor → repuser.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-050', 'pt', null, '"Vacina e soro são imunobiológicos: ______ confere imunidade passiva; ______, imunidade ativa." Completam corretamente as lacunas:', '["este / aquela","esta / aquele","aquela / este","esse / essa","aquele / esta"]'::jsonb, 0, '"Este" retoma o termo mais próximo (o soro, imunidade passiva) e "aquela" o mais distante (a vacina, imunidade ativa).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-051', 'pt', null, 'De acordo com a norma-padrão, assinale a frase correta:', '["Esta é a reunião em que discutimos a escala.","Esta é a reunião onde discutimos a escala.","O paciente cujo o prontuário sumiu foi transferido.","Este é o setor que eu trabalho.","A técnica que eu falei chegou."]'::jsonb, 0, '"Onde" só indica lugar físico. Correções: cujo prontuário (sem artigo); setor em que trabalho; técnica de quem (de que) falei.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-052', 'pt', null, 'Na frase "A coordenação ratificou a informação", o verbo "ratificou" significa:', '["confirmou.","corrigiu.","anulou.","questionou.","divulgou."]'::jsonb, 0, 'Ratificar = confirmar; retificar = corrigir (parônimos).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-053', 'pt', null, 'Assinale a frase em que o parônimo está empregado corretamente:', '["O paciente agitado corre risco iminente de queda.","O cirurgião eminente de queda foi afastado.","A enfermeira fez uma descrição do sigilo profissional, guardando segredo.","O médico vai deferir o diagnóstico em outro paciente.","O tráfego de drogas é crime."]'::jsonb, 0, 'Iminente = prestes a acontecer; eminente = ilustre. Discrição = reserva; deferir = conceder; tráfico = comércio ilegal.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-054', 'pt', null, 'Em "Como estava chovendo muito, o atendimento atrasou", a oração destacada "Como estava chovendo muito" expressa:', '["causa.","comparação.","conformidade.","concessão.","finalidade."]'::jsonb, 0, '"Como" anteposto à principal, com sentido de "porque", é conjunção causal.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-055', 'pt', null, 'Em "Estude com antecedência, pois a prova está próxima", a conjunção "pois" é:', '["explicativa.","conclusiva.","adversativa.","alternativa.","aditiva."]'::jsonb, 0, '"Pois" antes do verbo, após oração imperativa, introduz explicação. Seria conclusivo se posposto ao verbo ("está, pois, próxima").') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-056', 'pt', null, 'Assinale a alternativa em que o plural de todas as palavras está correto:', '["cidadãos, capitães, pães.","cidadões, capitães, pães.","cidadãos, capitões, pães.","cidadãos, capitães, pãos.","cidadões, capitões, pãos."]'::jsonb, 0, 'Cidadão → cidadãos; capitão → capitães; pão → pães.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-057', 'pt', null, 'Assinale a frase correta quanto ao uso de "mal" e "mau":', '["O paciente passou mal durante a noite.","Ele é um mal profissional.","Foi um mau-entendido.","Mau chegou, já foi atendido.","Ela agiu de mau humor ontem e mau hoje."]'::jsonb, 0, '"Mal" é advérbio (oposto de bem) ou conjunção (assim que); "mau" é adjetivo (oposto de bom). Correto: mau profissional, mal-entendido, mal chegou.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-058', 'pt', null, 'Assinale a frase em que a expressão destacada está empregada corretamente:', '["Estudou todos os dias a fim de ser aprovada no concurso.","Estudou todos os dias afim de ser aprovada no concurso.","Somos profissionais de áreas a fim.","Ela não estava afim de trabalhar.","Fizeram tudo afim de evitar o erro."]'::jsonb, 0, '"A fim de" indica finalidade; "afim" significa semelhante, que tem afinidade (áreas afins).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-059', 'pt', null, 'Em "Ela lê Machado de Assis todos os dias", ocorre a figura de linguagem chamada:', '["metonímia, pois o autor é citado no lugar da obra.","metáfora.","hipérbole.","antítese.","eufemismo."]'::jsonb, 0, 'Metonímia: substituição de um termo por outro com o qual mantém relação de proximidade (autor pela obra).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-060', 'pt', null, 'Assinale a frase corretamente pontuada:', '["O médico prescreveu o medicamento, e a técnica o administrou.","O médico, prescreveu o medicamento e a técnica o administrou.","O médico prescreveu, o medicamento e a técnica o administrou.","O médico prescreveu o medicamento e a técnica, o administrou.","O médico prescreveu o medicamento e, a técnica o administrou."]'::jsonb, 0, 'Admite-se vírgula antes de "e" quando as orações coordenadas têm sujeitos diferentes. Não se separa sujeito de verbo nem verbo de complemento.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-001', 'sus', null, 'Segundo o art. 196 da Constituição Federal de 1988, a saúde é:', '["direito de todos e dever do Estado, garantido mediante políticas sociais e econômicas que visem à redução do risco de doença e ao acesso universal e igualitário às ações e serviços.","direito dos contribuintes da previdência social e dever do Estado.","dever exclusivo da família, cabendo ao Estado apenas ações complementares.","direito de todos, sendo o acesso gratuito restrito aos comprovadamente carentes.","dever dos municípios, cabendo à União apenas a fiscalização."]'::jsonb, 0, 'Texto literal do art. 196 da CF/88: universalidade e igualdade de acesso, sem vínculo com contribuição previdenciária.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-002', 'sus', null, 'De acordo com o art. 198 da CF/88, é diretriz das ações e serviços públicos de saúde:', '["a participação da comunidade.","a centralização das ações na esfera federal.","a prioridade para as atividades assistenciais em detrimento das preventivas.","a direção compartilhada entre os entes em cada esfera de governo.","o atendimento restrito à atenção básica."]'::jsonb, 0, 'Diretrizes do art. 198: descentralização, com direção ÚNICA em cada esfera; atendimento integral, com prioridade para as atividades preventivas, sem prejuízo das assistenciais; e participação da comunidade.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-003', 'sus', null, 'Conforme a Lei nº 8.142/1990, a Conferência de Saúde:', '["reunir-se-á a cada quatro anos, com a representação dos vários segmentos sociais, para avaliar a situação de saúde e propor diretrizes para a formulação da política de saúde.","reunir-se-á a cada dois anos, convocada exclusivamente pelo Conselho de Saúde.","tem caráter permanente e deliberativo, reunindo-se mensalmente.","é composta exclusivamente por gestores e prestadores de serviço.","é convocada apenas pelo Ministério Público."]'::jsonb, 0, 'Conferência: a cada 4 anos, convocada pelo Poder Executivo ou, extraordinariamente, por ela ou pelo Conselho. O caráter permanente e deliberativo é do Conselho de Saúde.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-004', 'sus', null, 'Segundo a Lei nº 8.142/1990, a representação dos usuários nos Conselhos de Saúde e Conferências será:', '["paritária em relação ao conjunto dos demais segmentos.","equivalente a um terço do total de membros.","minoritária, para garantir a governabilidade do gestor.","definida livremente pelo gestor municipal.","igual apenas à representação dos prestadores privados."]'::jsonb, 0, 'Art. 1º, §4º: usuários = 50% (paridade com o conjunto dos demais segmentos: governo, prestadores e trabalhadores).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-005', 'sus', null, 'Sobre a participação da iniciativa privada no SUS, é correto afirmar que:', '["as instituições privadas podem participar de forma complementar, tendo preferência as entidades filantrópicas e as sem fins lucrativos.","é vedada qualquer participação de instituições privadas no SUS.","as empresas com fins lucrativos têm preferência na contratação.","é livre a participação direta de empresas ou capitais estrangeiros na assistência à saúde.","a contratação dispensa contrato ou convênio quando houver insuficiência de serviços públicos."]'::jsonb, 0, 'CF, art. 199, §1º e Lei 8.080/90: participação complementar, mediante contrato de direito público ou convênio, com preferência às filantrópicas e sem fins lucrativos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-006', 'sus', null, 'De acordo com o Decreto nº 7.508/2011, são Portas de Entrada às ações e aos serviços de saúde nas Redes de Atenção à Saúde os serviços:', '["de atenção primária; de atenção de urgência e emergência; de atenção psicossocial; e especiais de acesso aberto.","exclusivamente dos hospitais universitários.","de ambulatórios de especialidades, mediante encaminhamento particular.","de consultórios privados conveniados.","de laboratórios de análises clínicas e de imagem."]'::jsonb, 0, 'Art. 9º do Decreto 7.508/2011.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-007', 'sus', null, 'Segundo o Decreto nº 7.508/2011, o acordo de colaboração firmado entre entes federativos para organizar e integrar as ações e serviços de saúde na rede regionalizada e hierarquizada denomina-se:', '["Contrato Organizativo da Ação Pública da Saúde (COAP).","Relação Nacional de Ações e Serviços de Saúde (RENASES).","Mapa da Saúde.","Comissão Intergestores Tripartite (CIT).","Protocolo Clínico e Diretriz Terapêutica (PCDT)."]'::jsonb, 0, 'COAP: define responsabilidades, indicadores, metas, recursos e critérios de avaliação. RENASES é a relação de ações e serviços; Mapa da Saúde é a descrição geográfica dos recursos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-008', 'sus', null, 'Segundo a Lei nº 8.080/1990, entende-se por vigilância epidemiológica:', '["um conjunto de ações que proporcionam o conhecimento, a detecção ou prevenção de qualquer mudança nos fatores determinantes e condicionantes de saúde individual ou coletiva, para recomendar e adotar medidas de prevenção e controle das doenças ou agravos.","um conjunto de ações capaz de eliminar, diminuir ou prevenir riscos à saúde decorrentes do meio ambiente, da produção e circulação de bens e da prestação de serviços.","um conjunto de atividades destinadas à promoção e proteção da saúde dos trabalhadores.","a política de assistência farmacêutica do SUS.","a fiscalização exclusiva de estabelecimentos comerciais de alimentos."]'::jsonb, 0, 'Art. 6º, §2º. A segunda alternativa é a definição de vigilância sanitária (§1º) e a terceira, de saúde do trabalhador (§3º).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-009', 'sus', null, 'A Lei nº 8.080/1990 (incluído pela Lei nº 11.108/2005) garante à parturiente, nos serviços do SUS, próprios ou conveniados, a presença de:', '["um acompanhante de sua indicação durante todo o período de trabalho de parto, parto e pós-parto imediato.","um acompanhante apenas no pós-parto.","acompanhante somente se for o pai da criança.","até dois acompanhantes, mediante pagamento de taxa.","acompanhante apenas em hospitais privados."]'::jsonb, 0, 'Art. 19-J da Lei 8.080/90: 1 acompanhante indicado pela parturiente, no trabalho de parto, parto e pós-parto imediato.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-010', 'sus', null, 'Para receberem os recursos do Fundo Nacional de Saúde de forma regular e automática, os Municípios deverão contar com os itens abaixo, EXCETO:', '["consórcio intermunicipal de saúde obrigatório.","Fundo de Saúde.","Conselho de Saúde com composição paritária.","plano de saúde.","relatórios de gestão."]'::jsonb, 0, 'Art. 4º da Lei 8.142/90: Fundo, Conselho paritário, plano de saúde, relatórios de gestão, contrapartida de recursos no orçamento e comissão de elaboração do PCCS. Consórcio não é exigência.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-011', 'sus', null, 'Segundo a Lei nº 8.080/1990, o dever do Estado de garantir a saúde:', '["não exclui o das pessoas, da família, das empresas e da sociedade.","exclui a responsabilidade da família.","é transferido às empresas privadas em caso de insuficiência.","limita-se ao atendimento hospitalar.","aplica-se apenas aos contribuintes da previdência."]'::jsonb, 0, 'Art. 2º, §2º, da Lei 8.080/90.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-012', 'sus', null, 'A Lei nº 8.080/1990 cita como determinantes e condicionantes da saúde, entre outros, os seguintes, EXCETO:', '["a religião.","a alimentação.","a moradia.","o saneamento básico.","o trabalho e a renda."]'::jsonb, 0, 'Art. 3º: alimentação, moradia, saneamento, meio ambiente, trabalho, renda, educação, atividade física, transporte, lazer e acesso a bens e serviços essenciais.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-013', 'sus', null, 'Segundo a Lei nº 8.080/1990, o Sistema Único de Saúde é constituído pelo conjunto de ações e serviços de saúde prestados:', '["por órgãos e instituições públicas federais, estaduais e municipais, da administração direta e indireta e das fundações mantidas pelo Poder Público.","exclusivamente pelos hospitais federais.","apenas pelas secretarias municipais de saúde.","por qualquer prestador privado, independentemente de contrato.","somente pelas operadoras de planos de saúde."]'::jsonb, 0, 'Art. 4º. A iniciativa privada participa apenas em caráter complementar (§2º).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-014', 'sus', null, 'NÃO é objetivo do SUS, segundo o art. 5º da Lei nº 8.080/1990:', '["financiar planos privados de saúde para a população.","identificar e divulgar os fatores condicionantes e determinantes da saúde.","formular política de saúde destinada a promover a redução de riscos de doenças.","prestar assistência por intermédio de ações de promoção, proteção e recuperação da saúde.","realizar ações assistenciais integradas com atividades preventivas."]'::jsonb, 0, 'São três os objetivos do art. 5º: identificar/divulgar condicionantes; formular política de saúde; prestar assistência integrada.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-015', 'sus', null, 'Está incluída no campo de atuação do SUS, conforme o art. 6º da Lei nº 8.080/1990:', '["a ordenação da formação de recursos humanos na área de saúde.","a fiscalização do sistema financeiro nacional.","a regulação do comércio exterior de bens de consumo.","a gestão da previdência social.","a fiscalização de concursos públicos."]'::jsonb, 0, 'O art. 6º inclui ainda vigilâncias, assistência farmacêutica, saneamento (participação), vigilância nutricional e fiscalização de produtos, entre outros.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-016', 'sus', null, 'Segundo a Lei nº 8.080/1990, a integralidade de assistência é entendida como:', '["conjunto articulado e contínuo das ações e serviços preventivos e curativos, individuais e coletivos, exigidos para cada caso em todos os níveis de complexidade do sistema.","acesso aos serviços de saúde apenas na atenção básica.","atendimento igual para todos, sem considerar necessidades.","gratuidade de todos os serviços privados.","atendimento exclusivamente hospitalar."]'::jsonb, 0, 'Art. 7º, II, da Lei 8.080/90.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-017', 'sus', null, 'Entre os princípios do SUS previstos no art. 7º da Lei nº 8.080/1990, está a:', '["preservação da autonomia das pessoas na defesa de sua integridade física e moral.","centralização da gestão no Ministério da Saúde.","prioridade de atendimento aos contribuintes.","cobrança de taxas de manutenção dos serviços.","restrição da informação ao paciente sobre sua saúde."]'::jsonb, 0, 'Art. 7º, III. Também é princípio o direito à informação, às pessoas assistidas, sobre sua saúde (V).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-018', 'sus', null, 'A organização dos serviços públicos de modo a evitar duplicidade de meios para fins idênticos é, segundo a Lei nº 8.080/1990:', '["um princípio do SUS.","uma atribuição exclusiva da iniciativa privada.","uma vedação aos municípios.","um requisito para habilitação de planos de saúde.","uma competência exclusiva do Conselho Nacional de Saúde."]'::jsonb, 0, 'Art. 7º, XIII.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-019', 'sus', null, 'Segundo a Lei nº 8.080/1990, as ações e serviços de saúde executados pelo SUS serão organizados:', '["de forma regionalizada e hierarquizada em níveis de complexidade crescente.","de forma centralizada na União.","sem qualquer hierarquia entre níveis de atenção.","exclusivamente por meio de hospitais de alta complexidade.","de acordo com a capacidade de pagamento do usuário."]'::jsonb, 0, 'Art. 8º.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-020', 'sus', null, 'De acordo com a Lei nº 8.080/1990, no âmbito dos Municípios, a direção do SUS é exercida:', '["pela respectiva Secretaria de Saúde ou órgão equivalente.","pelo Ministério da Saúde.","pela Secretaria Estadual de Saúde.","pelo Conselho Municipal de Saúde.","pela Câmara de Vereadores."]'::jsonb, 0, 'Art. 9º: União – Ministério da Saúde; Estados/DF e Municípios – Secretaria de Saúde ou órgão equivalente.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-021', 'sus', null, 'Segundo a Lei nº 8.080/1990, para desenvolver em conjunto as ações e os serviços de saúde que lhes correspondam, os Municípios poderão constituir:', '["consórcios.","autarquias federais.","operadoras de planos de saúde.","conselhos tutelares.","agências reguladoras."]'::jsonb, 0, 'Art. 10. Aplica-se aos consórcios o princípio da direção única.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-022', 'sus', null, 'Segundo a Lei nº 8.080/1990, as comissões intersetoriais de âmbito nacional são:', '["subordinadas ao Conselho Nacional de Saúde.","subordinadas à Presidência da República.","vinculadas às Câmaras Municipais.","órgãos do Poder Judiciário.","independentes de qualquer instância do SUS."]'::jsonb, 0, 'Art. 12. Têm a finalidade de articular políticas e programas de interesse para a saúde.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-023', 'sus', null, 'As Comissões Intergestores Bipartite e Tripartite são reconhecidas pela Lei nº 8.080/1990 como:', '["foros de negociação e pactuação entre gestores quanto aos aspectos operacionais do SUS.","órgãos de controle social com participação paritária de usuários.","instâncias de julgamento de processos éticos.","órgãos executores de assistência hospitalar.","conselhos de classe profissional."]'::jsonb, 0, 'Art. 14-A (incluído pela Lei 12.466/2011).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-024', 'sus', null, 'Compete à direção municipal do SUS, segundo o art. 18 da Lei nº 8.080/1990:', '["planejar, organizar, controlar e avaliar as ações e os serviços de saúde e gerir e executar os serviços públicos de saúde.","definir e coordenar os sistemas de redes integradas de alta complexidade em todo o país.","elaborar normas para regular as relações entre o SUS e os serviços privados em âmbito nacional.","formular a política nacional de sangue e hemoderivados.","controlar portos, aeroportos e fronteiras."]'::jsonb, 0, 'As demais alternativas são competências da direção nacional (art. 16).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-025', 'sus', null, 'Compete à direção nacional do SUS, segundo a Lei nº 8.080/1990:', '["definir e coordenar os sistemas de redes integradas de assistência de alta complexidade.","executar diretamente os serviços de atenção básica em cada bairro.","gerir os laboratórios públicos municipais.","executar a vigilância sanitária de padarias e restaurantes locais.","contratar agentes comunitários de saúde em cada município."]'::jsonb, 0, 'Art. 16. A execução local é atribuição predominantemente municipal.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-026', 'sus', null, 'O Subsistema de Atenção à Saúde Indígena, previsto na Lei nº 8.080/1990, é financiado:', '["pela União, com recursos próprios, podendo Estados, Municípios e outras instituições atuar complementarmente.","exclusivamente pelos municípios onde estão as aldeias.","pelas próprias comunidades indígenas.","por organismos internacionais, obrigatoriamente.","pelos planos de saúde privados."]'::jsonb, 0, 'Art. 19-C (Lei 9.836/1999).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-027', 'sus', null, 'Segundo a Lei nº 8.080/1990, o atendimento e a internação domiciliares só poderão ser realizados:', '["por indicação médica, com expressa concordância do paciente e de sua família.","por solicitação do Conselho de Saúde.","quando não houver leito hospitalar, independentemente da vontade do paciente.","por determinação judicial.","apenas para pacientes com plano de saúde."]'::jsonb, 0, 'Art. 19-I, §3º (Lei 10.424/2002).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-028', 'sus', null, 'Segundo a Lei nº 8.080/1990 (redação da Lei nº 12.401/2011), a assistência terapêutica integral inclui a dispensação de medicamentos cuja prescrição esteja em conformidade com:', '["as diretrizes terapêuticas definidas em protocolo clínico para a doença ou agravo.","a preferência do usuário.","a indicação da indústria farmacêutica.","qualquer prescrição, inclusive de medicamentos sem registro.","a lista de medicamentos importados."]'::jsonb, 0, 'Art. 19-M. Na falta de protocolo, observam-se as relações de medicamentos (RENAME e listas complementares).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-029', 'sus', null, 'Segundo a Lei nº 8.080/1990, são vedados, em todas as esferas de gestão do SUS:', '["o pagamento, o ressarcimento ou o reembolso de medicamento experimental ou sem registro na ANVISA.","a dispensação de medicamentos da RENAME.","a incorporação de novas tecnologias.","a assistência farmacêutica.","o uso de protocolos clínicos."]'::jsonb, 0, 'Art. 19-T (Lei 12.401/2011), ressalvadas exceções previstas em lei.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-030', 'sus', null, 'A incorporação, exclusão ou alteração de medicamentos e tecnologias pelo SUS é atribuição do Ministério da Saúde, assessorado pela:', '["Comissão Nacional de Incorporação de Tecnologias no SUS (CONITEC).","Agência Nacional de Saúde Suplementar (ANS).","Comissão Intergestores Bipartite.","Conselho Federal de Medicina.","Câmara dos Deputados."]'::jsonb, 0, 'Art. 19-Q da Lei 8.080/90.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-031', 'sus', null, 'Segundo a Lei nº 8.080/1990, os recursos financeiros do SUS serão depositados em conta especial, em cada esfera de atuação, e movimentados sob fiscalização:', '["dos respectivos Conselhos de Saúde.","exclusivamente do Ministério Público.","das operadoras privadas.","do Banco Central.","dos sindicatos de trabalhadores da saúde."]'::jsonb, 0, 'Art. 33.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-032', 'sus', null, 'O processo de planejamento e orçamento do SUS, segundo a Lei nº 8.080/1990, será:', '["ascendente, do nível local até o federal, ouvidos seus órgãos deliberativos.","descendente, do nível federal ao local.","definido exclusivamente pelo Ministério da Saúde.","elaborado apenas pelos estados.","anual e sem participação dos conselhos."]'::jsonb, 0, 'Art. 36.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-033', 'sus', null, 'Segundo a Lei nº 8.080/1990, a gratuidade das ações e serviços de saúde fica preservada:', '["nos serviços públicos contratados e nos privados contratados ou conveniados.","apenas nos hospitais universitários.","somente para pessoas de baixa renda.","apenas na atenção básica.","somente em situações de emergência."]'::jsonb, 0, 'Art. 43.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-034', 'sus', null, 'Segundo a Lei nº 8.142/1990, o Conselho de Saúde:', '["tem caráter permanente e deliberativo e atua na formulação de estratégias e no controle da execução da política de saúde, inclusive nos aspectos econômicos e financeiros.","reúne-se a cada quatro anos.","tem caráter apenas consultivo.","é formado exclusivamente por usuários.","tem suas decisões homologadas pelo Ministério Público."]'::jsonb, 0, 'Art. 1º, §2º. As decisões são homologadas pelo chefe do poder legalmente constituído em cada esfera de governo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-035', 'sus', null, 'Segundo a Lei nº 8.142/1990, terão representação no Conselho Nacional de Saúde:', '["o Conselho Nacional de Secretários de Saúde (CONASS) e o Conselho Nacional de Secretarias Municipais de Saúde (CONASEMS).","a Ordem dos Advogados do Brasil e o Ministério Público.","apenas os conselhos de classe profissional.","o Senado Federal e a Câmara dos Deputados.","as operadoras de planos de saúde, obrigatoriamente."]'::jsonb, 0, 'Art. 1º, §3º.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-036', 'sus', null, 'Segundo a Lei nº 8.142/1990, dos recursos destinados à cobertura das ações e serviços a serem implementados por Municípios, Estados e DF, serão repassados aos Municípios, no mínimo:', '["70%.","30%.","50%.","15%.","100%."]'::jsonb, 0, 'Art. 3º, §2º: pelo menos 70% aos Municípios, afetando-se o restante aos Estados.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-037', 'sus', null, 'Segundo a Lei nº 8.142/1990, quando o Município não atender aos requisitos para recebimento de recursos (Fundo, Conselho, plano etc.):', '["os recursos serão administrados pelo Estado ou pela União.","os recursos serão perdidos definitivamente.","o prefeito será afastado.","o Conselho Municipal administrará os recursos.","os recursos serão repassados a instituições privadas."]'::jsonb, 0, 'Art. 4º, parágrafo único.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-038', 'sus', null, 'Segundo o art. 197 da Constituição Federal, as ações e serviços de saúde:', '["são de relevância pública, cabendo ao Poder Público dispor sobre sua regulamentação, fiscalização e controle.","são de interesse exclusivamente privado.","só podem ser executados diretamente pelo Estado.","são regulados apenas pelos municípios.","não podem ser executados por pessoa física."]'::jsonb, 0, 'A execução pode ser direta ou por terceiros, inclusive pessoa física ou jurídica de direito privado.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-039', 'sus', null, 'De acordo com a Constituição Federal, é vedada:', '["a destinação de recursos públicos para auxílios ou subvenções às instituições privadas com fins lucrativos.","a participação de entidades filantrópicas no SUS.","a contratação de serviços privados de forma complementar.","a participação da comunidade no SUS.","a existência de serviços privados de saúde."]'::jsonb, 0, 'Art. 199, §2º.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-040', 'sus', null, 'Segundo a Constituição Federal, quanto à remoção de órgãos, tecidos e substâncias humanas para fins de transplante, pesquisa e tratamento:', '["é vedado todo tipo de comercialização.","é permitida a venda mediante autorização judicial.","é permitida a comercialização entre parentes.","a comercialização é livre para fins de pesquisa.","a comercialização depende de autorização do Conselho de Saúde."]'::jsonb, 0, 'Art. 199, §4º. O mesmo vale para coleta, processamento e transfusão de sangue e derivados.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-041', 'sus', null, 'Compete ao SUS, nos termos do art. 200 da Constituição Federal, EXCETO:', '["julgar os crimes contra a saúde pública.","executar as ações de vigilância sanitária e epidemiológica e de saúde do trabalhador.","ordenar a formação de recursos humanos na área de saúde.","participar da formulação da política e da execução das ações de saneamento básico.","colaborar na proteção do meio ambiente, nele compreendido o do trabalho."]'::jsonb, 0, 'Julgar crimes é função do Poder Judiciário.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-042', 'sus', null, 'Segundo a Constituição Federal, o SUS será financiado:', '["com recursos do orçamento da seguridade social, da União, dos Estados, do DF e dos Municípios, além de outras fontes.","exclusivamente com recursos da União.","exclusivamente com contribuições dos usuários.","apenas com recursos municipais.","por meio de taxas cobradas nos atendimentos."]'::jsonb, 0, 'Art. 198, §1º.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-043', 'sus', null, 'Segundo a Lei Complementar nº 141/2012, os Municípios devem aplicar anualmente em ações e serviços públicos de saúde, no mínimo:', '["15% da arrecadação de impostos e transferências constitucionais.","12% da arrecadação de impostos.","5% do orçamento total.","25% da arrecadação de impostos.","30% da receita corrente líquida."]'::jsonb, 0, 'Municípios: 15%; Estados: 12%. A União segue regra própria definida na Constituição.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-044', 'sus', null, 'Segundo a Lei Complementar nº 141/2012, NÃO constitui despesa com ações e serviços públicos de saúde, para fins de apuração do mínimo constitucional:', '["a merenda escolar.","a vigilância em saúde.","a atenção integral e universal à saúde em todos os níveis de complexidade.","a capacitação de pessoal de saúde do SUS.","a produção e aquisição de medicamentos e insumos para o SUS."]'::jsonb, 0, 'O art. 4º exclui, entre outros, merenda escolar, aposentadorias e pensões, limpeza urbana e assistência social.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-045', 'sus', null, 'Segundo o Decreto nº 7.508/2011, Região de Saúde é:', '["o espaço geográfico contínuo constituído por agrupamentos de Municípios limítrofes, delimitado a partir de identidades culturais, econômicas e sociais e de redes de comunicação e infraestrutura de transportes compartilhados.","o território de abrangência de uma equipe de saúde da família.","a área de atuação de um único hospital.","o conjunto de estados de uma macrorregião do IBGE.","o bairro onde reside o usuário."]'::jsonb, 0, 'Art. 2º, I, do Decreto 7.508/2011.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-046', 'sus', null, 'Segundo o Decreto nº 7.508/2011, para ser instituída, a Região de Saúde deve conter, no mínimo, ações e serviços de, EXCETO:', '["assistência odontológica privada.","atenção primária.","urgência e emergência.","atenção psicossocial.","vigilância em saúde."]'::jsonb, 0, 'Art. 5º: atenção primária, urgência e emergência, atenção psicossocial, atenção ambulatorial especializada e hospitalar, e vigilância em saúde.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-047', 'sus', null, 'Segundo o Decreto nº 7.508/2011, a descrição geográfica da distribuição de recursos humanos e de ações e serviços de saúde ofertados pelo SUS e pela iniciativa privada denomina-se:', '["Mapa da Saúde.","Rede de Atenção à Saúde.","Região de Saúde.","Protocolo Clínico.","Contrato Organizativo da Ação Pública."]'::jsonb, 0, 'Art. 2º, V. É usado na identificação das necessidades de saúde e no planejamento.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-048', 'sus', null, 'Segundo o Decreto nº 7.508/2011, o acesso universal e igualitário à assistência farmacêutica pressupõe, cumulativamente, EXCETO:', '["possuir plano de saúde privado.","estar o usuário assistido por ações e serviços de saúde do SUS.","ter o medicamento sido prescrito por profissional de saúde no exercício regular de suas funções no SUS.","estar a prescrição em conformidade com a RENAME e os PCDT.","ter a dispensação ocorrido em unidades indicadas pela direção do SUS."]'::jsonb, 0, 'Art. 28 do Decreto 7.508/2011.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-049', 'sus', null, 'Segundo o Decreto nº 7.508/2011, a Comissão Intergestores Regional (CIR) atua no âmbito:', '["regional, vinculada à Secretaria Estadual de Saúde.","nacional, vinculada ao Ministério da Saúde.","estadual, vinculada à Assembleia Legislativa.","municipal, vinculada à Câmara de Vereadores.","internacional, vinculada à OMS."]'::jsonb, 0, 'CIT: União; CIB: Estado; CIR: Região de Saúde (vinculada à SES para efeitos administrativos e operacionais).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-050', 'sus', null, 'Segundo o Decreto nº 7.508/2011, o acesso universal, igualitário e ordenado às ações e serviços de saúde se inicia pelas Portas de Entrada do SUS e se completa na rede regionalizada e hierarquizada. Esse acesso será ordenado pela:', '["atenção primária.","atenção hospitalar.","regulação judicial.","iniciativa privada.","atenção de alta complexidade."]'::jsonb, 0, 'Art. 11: o acesso será ordenado pela atenção primária, de acordo com a avaliação da gravidade do risco individual e coletivo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-051', 'sus', null, 'Segundo a Política Nacional de Atenção Básica (Portaria nº 2.436/2017), são princípios do SUS e da Rede de Atenção à Saúde a serem operacionalizados na Atenção Básica:', '["universalidade, equidade e integralidade.","centralização, hierarquização e privatização.","territorialização, adscrição e resolutividade.","regionalização, cogestão e ambiência.","longitudinalidade, coordenação e ordenação."]'::jsonb, 0, 'Os princípios são universalidade, equidade e integralidade. Territorialização, longitudinalidade etc. são diretrizes.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-052', 'sus', null, 'Segundo a PNAB (Portaria nº 2.436/2017), a composição mínima da equipe de Saúde da Família (eSF) é:', '["médico, enfermeiro, auxiliar e/ou técnico de enfermagem e agente comunitário de saúde.","médico, dentista e farmacêutico.","enfermeiro e agente de combate às endemias, apenas.","médico, psicólogo e assistente social.","médico e técnico de enfermagem, apenas."]'::jsonb, 0, 'Podem ser acrescentados o agente de combate às endemias e os profissionais de saúde bucal.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-053', 'sus', null, 'Segundo a PNAB (Portaria nº 2.436/2017), a população adscrita por equipe de Atenção Básica e de Saúde da Família recomendada é de:', '["2.000 a 3.500 pessoas.","500 a 1.000 pessoas.","5.000 a 8.000 pessoas.","10.000 pessoas.","até 750 famílias por agente comunitário."]'::jsonb, 0, 'PNAB 2017: 2.000 a 3.500 pessoas, podendo variar conforme vulnerabilidade e critérios locais.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-054', 'sus', null, 'Na PNAB, a diretriz que se refere à continuidade da relação de cuidado, com construção de vínculo e responsabilização entre profissionais e usuários ao longo do tempo, é a:', '["longitudinalidade do cuidado.","territorialização.","resolutividade.","regionalização.","população adscrita."]'::jsonb, 0, 'Longitudinalidade = acompanhamento ao longo do tempo, de modo permanente e consistente.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-055', 'sus', null, 'Segundo a PNAB (Portaria nº 2.436/2017), a carga horária dos profissionais da equipe de Saúde da Família é de:', '["40 horas semanais.","20 horas semanais.","30 horas semanais.","12 horas por plantão.","60 horas semanais."]'::jsonb, 0, 'Na eSF todos os profissionais cumprem 40 h semanais. Equipes de Atenção Básica (eAB) podem ter carga mínima de 10 h por categoria.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-056', 'sus', null, 'Segundo a Carta dos Direitos dos Usuários da Saúde (Portaria nº 1.820/2009), é direito da pessoa:', '["ser identificada pelo nome e sobrenome civil, nunca por número, código ou nome da doença.","escolher livremente o profissional em qualquer serviço, sem regulação.","receber medicamentos sem prescrição.","ter acesso ao prontuário de outros pacientes.","ser atendida sem qualquer ordem de prioridade."]'::jsonb, 0, 'A Carta também garante o uso do nome social e o acesso ao próprio prontuário.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-057', 'sus', null, 'São diretrizes da Política Nacional de Humanização (HumanizaSUS):', '["acolhimento, clínica ampliada, cogestão, ambiência, valorização do trabalhador e defesa dos direitos dos usuários.","centralização das decisões e hierarquização rígida das equipes.","redução de custos por meio da privatização.","triagem por ordem de chegada e atendimento exclusivamente médico.","padronização dos atendimentos sem considerar singularidades."]'::jsonb, 0, 'A PNH (2003) busca transformar os modos de gerir e de cuidar, com protagonismo de usuários e trabalhadores.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-058', 'sus', null, 'O Pacto pela Saúde (2006) é composto por três dimensões:', '["Pacto pela Vida, Pacto em Defesa do SUS e Pacto de Gestão.","Pacto pela Vida, Pacto pela Morte Digna e Pacto Federativo.","Pacto de Financiamento, Pacto Privado e Pacto Social.","Pacto da Atenção Básica, Pacto Hospitalar e Pacto Farmacêutico.","Pacto Municipal, Pacto Estadual e Pacto Internacional."]'::jsonb, 0, 'Pacto pela Vida (prioridades sanitárias), em Defesa do SUS (repolitização) e de Gestão (responsabilidades dos entes).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-059', 'sus', null, 'Segundo a Lei nº 8.080/1990, a igualdade da assistência à saúde deve ocorrer:', '["sem preconceitos ou privilégios de qualquer espécie.","com prioridade aos contribuintes da previdência.","conforme a renda do usuário.","apenas entre usuários do mesmo município.","mediante pagamento de taxa de igualdade."]'::jsonb, 0, 'Art. 7º, IV, da Lei 8.080/90.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-060', 'sus', null, 'Segundo a Lei nº 8.142/1990, a Conferência de Saúde será convocada:', '["pelo Poder Executivo ou, extraordinariamente, por esta ou pelo Conselho de Saúde.","exclusivamente pelo Ministério Público.","pelo Poder Judiciário.","apenas pelos usuários, mediante abaixo-assinado.","pelo Congresso Nacional, a cada dez anos."]'::jsonb, 0, 'Art. 1º, §1º. Reúne-se a cada quatro anos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
